package main

import (
	"archive/zip"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

const extractDir = "/tmp/terraform-provider-workspace"

// HandleProviderUpload processes uploaded Terraform provider archives
// This Lambda function is invoked via Function URL to accept provider bundles
func HandleProviderUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Parse multipart form with 50MB limit
	err := r.ParseMultipartForm(50 << 20)
	if err != nil {
		http.Error(w, "Failed to parse form", http.StatusBadRequest)
		return
	}

	file, header, err := r.FormFile("provider_bundle")
	if err != nil {
		http.Error(w, "Missing provider_bundle field", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Validate file extension
	if !strings.HasSuffix(header.Filename, ".zip") {
		http.Error(w, "Only .zip files accepted", http.StatusBadRequest)
		return
	}

	// Save uploaded file temporarily
	tmpFile, err := os.CreateTemp("/tmp", "upload-*.zip")
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer os.Remove(tmpFile.Name())

	_, err = io.Copy(tmpFile, file)
	if err != nil {
		http.Error(w, "Failed to save upload", http.StatusInternalServerError)
		return
	}
	tmpFile.Close()

	// Extract and validate provider structure
	count, err := extractProviderBundle(tmpFile.Name())
	if err != nil {
		http.Error(w, fmt.Sprintf("Extraction failed: %v", err), http.StatusBadRequest)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "{\"status\": \"ok\", \"files_extracted\": %d}", count)
}

// extractProviderBundle extracts a zip archive containing Terraform provider files
func extractProviderBundle(zipPath string) (int, error) {
	reader, err := zip.OpenReader(zipPath)
	if err != nil {
		return 0, fmt.Errorf("invalid zip file: %w", err)
	}
	defer reader.Close()

	// Ensure extraction directory exists
	os.MkdirAll(extractDir, 0755)

	count := 0
	for _, f := range reader.File {
		// Skip directories
		if f.FileInfo().IsDir() {
			continue
		}

		// Construct target path - NOTE: filepath.Join does NOT sanitize ".." components
		// when they appear in the middle of a path
		targetPath := filepath.Join(extractDir, f.Name)

		// Basic extension check for provider files
		ext := filepath.Ext(targetPath)
		allowedExts := map[string]bool{".tf": true, ".json": true, ".hcl": true, ".go": true, ".mod": true, ".sum": true}
		if !allowedExts[ext] {
			continue
		}

		// Create parent directories
		os.MkdirAll(filepath.Dir(targetPath), 0755)

		// Extract file
		rc, err := f.Open()
		if err != nil {
			return count, fmt.Errorf("failed to open %s: %w", f.Name, err)
		}

		outFile, err := os.OpenFile(targetPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, f.Mode())
		if err != nil {
			rc.Close()
			return count, fmt.Errorf("failed to create %s: %w", targetPath, err)
		}

		_, err = io.Copy(outFile, rc)
		rc.Close()
		outFile.Close()
		if err != nil {
			return count, fmt.Errorf("failed to write %s: %w", targetPath, err)
		}
		count++
	}

	return count, nil
}

func main() {
	http.HandleFunc("/upload", HandleProviderUpload)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte(`{"status":"healthy"}`))
	})

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
